BEGIN;
GRANT USAGE ON SCHEMA public,auth TO authenticated;
GRANT ALL ON ALL TABLES IN SCHEMA public TO authenticated;
CREATE FUNCTION test_ocr_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF NOT coalesce(ok,false) THEN RAISE EXCEPTION 'FAIL: %',label;END IF;RAISE NOTICE 'PASS: %',label;END; $$;
CREATE FUNCTION test_ocr_reject(command text,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE command; EXCEPTION WHEN OTHERS THEN RAISE NOTICE 'PASS rejected: % [%]',label,SQLERRM;RETURN;END;RAISE EXCEPTION 'FAIL accepted: %',label;END; $$;
INSERT INTO auth.users(id,email) VALUES('91000000-0000-4000-8000-000000000001','ocr-director@example.test'),('91000000-0000-4000-8000-000000000002','ocr-client@example.test');
INSERT INTO staff_users(auth_id,nom,email,role,must_change_password) VALUES('91000000-0000-4000-8000-000000000001','OCR fixture','ocr-director@example.test','directeur',false);
INSERT INTO staff_permissions SELECT (jsonb_populate_record(NULL::staff_permissions,fn_default_permissions(s.role::text)||jsonb_build_object('id',gen_random_uuid(),'staff_id',s.id))).* FROM staff_users s ON CONFLICT(staff_id) DO NOTHING;
INSERT INTO clients(id,user_id,nom,cp,email) VALUES('92000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000002','Fixture','97400','ocr-client@example.test');
INSERT INTO colis(id,client_id,statut) VALUES('93000000-0000-4000-8000-000000000001','92000000-0000-4000-8000-000000000001','en_preparation');
INSERT INTO factures(id,colis_id,vendeur,montant,fichier_url) VALUES('94000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001','Fixture',100,'93000000-0000-4000-8000-000000000001/a.pdf');
INSERT INTO ocr_extractions(id,facture_id,document_hash,total,lines) SELECT '95000000-0000-4000-8000-000000000001','94000000-0000-4000-8000-000000000001','sha256-A',100,jsonb_build_array(jsonb_build_object('desc','Produit','qte',1,'prix',100,'cat',id)) FROM categories LIMIT 1;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.role','authenticated',true),set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000001',true);
SELECT test_ocr_reject($q$SELECT confirm_ocr_extraction('95000000-0000-4000-8000-000000000001')$q$,'Browser cannot bypass the document guard through the old RPC');
SELECT test_ocr_reject($q$SELECT confirm_ocr_extraction_current('95000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001/a.pdf','sha256-A')$q$,'Historical extraction requires verified binding before confirmation');
RESET ROLE;
UPDATE ocr_extractions SET document_file_url='93000000-0000-4000-8000-000000000001/a.pdf' WHERE id='95000000-0000-4000-8000-000000000001';
UPDATE factures SET fichier_url='93000000-0000-4000-8000-000000000001/b.pdf' WHERE id='94000000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated;
SELECT test_ocr_reject($q$SELECT confirm_ocr_extraction_current('95000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001/a.pdf','sha256-A')$q$,'File replacement after Edge hashing rejects the stale confirmation');
SELECT test_ocr_reject($q$SELECT confirm_ocr_extraction_current('95000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001/b.pdf','sha256-A')$q$,'Supplying a new path cannot rebind an old extraction');
SELECT test_ocr_assert((SELECT NOT valide FROM factures WHERE id='94000000-0000-4000-8000-000000000001') AND (SELECT count(*)=0 FROM lignes WHERE facture_id='94000000-0000-4000-8000-000000000001'),'Stale confirmation leaves approval and articles unchanged');
RESET ROLE;
UPDATE factures SET fichier_url='93000000-0000-4000-8000-000000000001/a.pdf' WHERE id='94000000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated;
SELECT test_ocr_reject($q$SELECT confirm_ocr_extraction_current('95000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001/a.pdf','wrong-hash')$q$,'A mismatched document hash is rejected');
SELECT set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000002',true);
SELECT test_ocr_reject($q$SELECT confirm_ocr_extraction_current('95000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001/a.pdf','sha256-A')$q$,'The customer cannot validate their own OCR extraction');
SELECT set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000001',true);
SELECT test_ocr_assert(confirm_ocr_extraction_current('95000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001/a.pdf','sha256-A')->>'success'='true','Current document confirms atomically');
SELECT test_ocr_assert(confirm_ocr_extraction_current('95000000-0000-4000-8000-000000000001','93000000-0000-4000-8000-000000000001/a.pdf','sha256-A')->>'reused'='true','Repeated current confirmation is idempotent');
SELECT test_ocr_assert((SELECT count(*)=1 FROM lignes WHERE facture_id='94000000-0000-4000-8000-000000000001'),'Repeated OCR confirmation never duplicates invoice lines');
ROLLBACK;
